import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matvec_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// One block computes one output element C[m] = dot(A[m, :], B[:])
// Vectorized loads via float4 using CuTe's recast, cooperative reduction across the block.
template <typename T, int Threads>
__global__ void matvec_kernel(
    const T* __restrict__ Aptr,
    const T* __restrict__ Bptr,
    T* __restrict__ Cptr,
    int M, int K)
{
  int m = blockIdx.x;
  if (m >= M) return;

  // Full tensors via CuTe
  Tensor mA = make_tensor(make_gmem_ptr(Aptr), make_shape(M, K), make_stride(K, 1));
  Tensor mB = make_tensor(make_gmem_ptr(Bptr), make_shape(K), make_stride(1));

  // Row slice for this block: shape (K)
  Tensor gA = mA(m, _);

  int tid = threadIdx.x;

  float acc = 0.0f;

  // Vectorized portion: try to recast to float4 view when possible
  constexpr int VecWidth = 4;
  int K4 = K / VecWidth;
  int Krem = K - K4 * VecWidth;

  if (K4 > 0) {
    // Use explicit pointer-based float4 reinterpretation to avoid CuTe
    // recast/compose issues with dynamically-sized layouts.
    const float4* Aptr4 = reinterpret_cast<const float4*>(Aptr + (size_t)m * K);
    const float4* Bptr4 = reinterpret_cast<const float4*>(Bptr);
    for (int i = tid; i < K4; i += Threads) {
      float4 a4 = Aptr4[i];
      float4 b4 = Bptr4[i];
      acc += a4.x * b4.x + a4.y * b4.y + a4.z * b4.z + a4.w * b4.w;
    }
  }

  // Remainder (scalar) portion
  int rem_start = K4 * VecWidth;
  for (int i = rem_start + tid; i < K; i += Threads) {
    float av = gA(i);
    float bv = mB(i);
    acc += av * bv;
  }

  // Block-level reduction: warp shuffle then shared memory across warps
  unsigned mask = 0xffffffffu;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    acc += __shfl_down_sync(mask, acc, offset);
  }

  __shared__ float warp_sums[Threads / 32];
  int lane = tid % 32;
  int warp_id = tid / 32;
  if (lane == 0) {
    warp_sums[warp_id] = acc;
  }
  __syncthreads();

  if (warp_id == 0) {
    float val = (lane < (Threads / 32)) ? warp_sums[lane] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      val += __shfl_down_sync(mask, val, offset);
    }
    if (lane == 0) {
      Cptr[m] = static_cast<T>(val);
    }
  }
}

torch::Tensor cute_matvec_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M,K)");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  int M = (int)A_c.size(0);
  int K = (int)A_c.size(1);

  int64_t Bnum = B_c.numel();
  TORCH_CHECK(Bnum == K, "B must have K elements");

  auto C = torch::empty({M, 1}, A.options());

  const float* Aptr = A_c.data_ptr<float>();
  const float* Bptr = B_c.data_ptr<float>();
  float* Cptr = C.data_ptr<float>();

  constexpr int Threads = 256;
  dim3 block(Threads);
  dim3 grid((unsigned)M);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  matvec_kernel<float, Threads><<<grid, block, 0, stream>>>(
      Aptr, Bptr, Cptr, M, K);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom CUTE kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec_forward(A.contiguous(), B.contiguous())

